// Simple test of threshold parsing logic
function parseAndValidateThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: {} };
  }

  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
  const thresholds = {};
  const errors = [];

  for (const threshStr of thresholdStrings) {
    const match = threshStr.match(/^([a-zA-Z_]+)=(.+)$/);
    if (!match) {
      errors.push(`Malformed threshold "${threshStr}". Expected format: <metric>=<number>`);
      continue;
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (!Number.isFinite(value)) {
      errors.push(`Threshold value for "${metricId}" is not a valid number: "${valueStr}"`);
      continue;
    }

    if (value < 0 || value > 1) {
      errors.push(`Threshold value for "${metricId}" must be between 0 and 1, got ${value}`);
      continue;
    }

    if (!validMetrics.includes(metricId)) {
      errors.push(`Unknown metric: "${metricId}". Valid metrics are: ${validMetrics.join(', ')}`);
      continue;
    }

    thresholds[metricId] = value;
  }

  if (errors.length > 0) {
    return { thresholds: {}, errors };
  }

  return { thresholds };
}

// Test cases
console.log('Test 1 - Valid threshold:');
console.log(parseAndValidateThresholds(['exact_match=0.9']));

console.log('\nTest 2 - Multiple thresholds:');
console.log(parseAndValidateThresholds(['exact_match=0.9', 'toxicity=0.95']));

console.log('\nTest 3 - Invalid format:');
console.log(parseAndValidateThresholds(['exact_match:0.9']));

console.log('\nTest 4 - Unknown metric:');
console.log(parseAndValidateThresholds(['unknown_metric=0.9']));

console.log('\nTest 5 - Value out of range:');
console.log(parseAndValidateThresholds(['exact_match=1.5']));

console.log('\nTest 6 - Invalid number:');
console.log(parseAndValidateThresholds(['exact_match=abc']));

console.log('\nTest 7 - No thresholds:');
console.log(parseAndValidateThresholds([]));
EOF
node /tmp/test_thresholds.js
